static uint32_t half2float(uint16_t h, uint32_t *mantissatable, uint32_t *exponenttable, /* <=== half2float */ 
                           uint16_t *offsettable)
{
    uint32_t f;

    f = mantissatable[offsettable[h >> 10] + (h & 0x3ff)] + exponenttable[h >> 10];

    return f;
}

